"use client";
import { useState } from "react";import { Button } from "@/components/ui/button";
export function ContactForm(){const[sent,setSent]=useState(false);if(sent)return <div className="rounded-3xl border border-gold-300/30 bg-gold-300/[.07] p-8"><h2 className="text-2xl font-semibold">Demande enregistrée</h2><p className="mt-3 text-zinc-400">Le formulaire fonctionne en mode démonstration. Il pourra ensuite être connecté à votre e-mail ou à n8n.</p></div>;return <form onSubmit={e=>{e.preventDefault();setSent(true)}} className="grid gap-5 rounded-3xl border border-white/10 bg-white/[.025] p-6 sm:p-9"><div className="grid gap-5 sm:grid-cols-2"><Field label="Nom"/><Field label="Entreprise"/></div><div className="grid gap-5 sm:grid-cols-2"><Field label="Téléphone" type="tel"/><Field label="E-mail" type="email"/></div><label className="grid gap-2 text-sm text-zinc-400">Message<textarea required rows={6} className="rounded-2xl border border-white/10 bg-black/50 px-4 py-3 text-white outline-none focus:border-gold-300/60" placeholder="Parlez-nous de votre activité..."/></label><Button type="submit">Envoyer ma demande</Button></form>}
function Field({label,type="text"}:{label:string;type?:string}){return <label className="grid gap-2 text-sm text-zinc-400">{label}<input required type={type} className="h-12 rounded-2xl border border-white/10 bg-black/50 px-4 text-white outline-none focus:border-gold-300/60"/></label>}
